<script lang="ts">
  import {searchableSelect} from '#lib/client/searchable-select.ts';
  import {onMount} from 'svelte';
  import {refreshAll} from '$app/navigation';
  import {command,permitted} from '#lib/client/api.ts';
  import type {AppData,Row} from '#lib/client/types.ts';
  import Icon from './Icon.svelte';
  let {data}:{data:AppData}=$props();
  let category=$state('sales');let channel=$state('in_app');let enabled=$state(true);let quietStart=$state('');let quietEnd=$state('');let digest=$state(false);let busy=$state(false);let error=$state('');let notice=$state('');
  const categories:Record<string,string>={sales:'Angebote & Aufträge',portal:'Kundenzugänge & Freigaben',planning:'Planung & Fertigung',purchasing:'Einkauf & Liefertermine',finance:'Rechnungen & Zahlungen',time:'Zeiten & Korrekturen',leave:'Urlaub & Abwesenheit',dispatch:'Einsatzplanung',security:'Sicherheit meines Zugangs',system:'Verarbeitung & System'};
  const preferences=$derived(Array.isArray(data.related?.notification_preferences)?data.related.notification_preferences:[]);
  const current=$derived(preferences.find(row=>row.category===category&&row.channel===channel));
  const emailAvailable=$derived(data.summary?.account?.emailDeliveryConfigured===true);
  const digestAvailable=$derived(data.summary?.account?.notificationDigestAvailable===true);
  function loadSelection(){const stored=preferences.find(row=>row.category===category&&row.channel===channel);enabled=stored?!!stored.enabled:channel==='in_app';quietStart=stored?.quiet_start?.slice(0,5)||'';quietEnd=stored?.quiet_end?.slice(0,5)||'';digest=!!stored?.digest;error='';notice='';}
  function edit(row:Row){category=row.category;channel=row.channel;loadSelection();}
  onMount(loadSelection);
  async function save(event:SubmitEvent){event.preventDefault();if(busy)return;error='';notice='';if(!!quietStart!==!!quietEnd){error='Bitte Beginn und Ende der Ruhezeit gemeinsam eintragen oder beide Felder leeren.';return;}busy=true;try{await command('communication.notification.preferences.update',undefined,{channel,category,enabled,quiet_start:quietStart||null,quiet_end:quietEnd||null,digest:channel==='email'&&digest});notice=channel==='email'&&enabled&&!emailAvailable?'Ihr E-Mail-Wunsch wurde gespeichert. Der Versand ist erst nach der bestätigten Einrichtung des E-Mail-Dienstes verfügbar.':'Ihre persönliche Auswahl wurde gespeichert.';await refreshAll().catch(()=>{});}catch(cause){error=cause instanceof Error?cause.message:'Die Mitteilungseinstellungen konnten nicht gespeichert werden.';}finally{busy=false;}}
</script>
{#if permitted(data,'tasks')}
<section class="panel mt"><header class="panel-header"><div><h2>Meine Mitteilungen</h2><p>Wählen Sie selbst, wie Sie über berechtigte Vorgänge informiert werden.</p></div><Icon name="bell" size={18}/></header>
  <form class="panel-body" onsubmit={save}>
    {#if error}<div class="notice error" role="alert"><Icon name="alert"/><div>{error}</div></div>{/if}{#if notice}<div class="notice info" role="status"><Icon name="check"/><div>{notice}</div></div>{/if}
    <div class="field-grid"><div class="field"><label for="notification-category">Themenbereich *</label><select use:searchableSelect={category} id="notification-category" bind:value={category} onchange={loadSelection} disabled={busy}>{#each Object.entries(categories) as [value,label]}<option {value}>{label}</option>{/each}</select><span class="field-help">Diese Auswahl ändert nur Ihre persönlichen Mitteilungen, keine Zugriffsrechte.</span></div><div class="field"><label for="notification-channel">Wo möchten Sie sie erhalten? *</label><select use:searchableSelect={channel} id="notification-channel" bind:value={channel} onchange={loadSelection} disabled={busy}><option value="in_app">In der Suite</option><option value="email">An meine geschäftliche E-Mail</option></select><span class="field-help">E-Mail bleibt ohne Ihre ausdrückliche Aktivierung ausgeschaltet.</span></div>
    <label class="check-field full"><input type="checkbox" bind:checked={enabled} disabled={busy}/><span>{channel==='email'?'Ich möchte E-Mails zu diesem Themenbereich erhalten.':'Mitteilungen zu diesem Themenbereich in der Suite anzeigen.'}</span></label>
    {#if channel==='email'&&!emailAvailable}<p class="field-help full">Der E-Mail-Versand ist für diesen Betrieb noch nicht bestätigt eingerichtet. Ihre Auswahl wird als persönlicher Wunsch gespeichert; sie bestätigt noch keine versandte E-Mail.</p>{/if}
    <div class="field"><label for="notification-quiet-start">Ruhezeit ab · optional</label><input id="notification-quiet-start" type="time" bind:value={quietStart} required={!!quietEnd} disabled={busy}/></div><div class="field"><label for="notification-quiet-end">Wieder informieren ab · optional</label><input id="notification-quiet-end" type="time" bind:value={quietEnd} required={!!quietStart} disabled={busy}/></div><p class="field-help full">Uhrzeiten gelten für die Betriebszeitzone Deutschland. Eine Ruhezeit kann über Mitternacht reichen. Beide Felder leer lassen, wenn Sie keine Ruhezeit wünschen.</p>
    {#if channel==='email'}<label class="check-field full"><input type="checkbox" bind:checked={digest} disabled={busy||!digestAvailable}/><span>Mehrere Hinweise als Zusammenfassung erhalten.</span></label>{#if digestAvailable}<p class="field-help full">Zusammenfassungen werden zum nächsten vorgesehenen Versand um 09:00 Uhr deutscher Betriebszeit vorgemerkt. Einzelne In-App-Mitteilungen bleiben erreichbar.</p>{/if}{#if !digestAvailable}<p class="field-help full">Die gebündelte Zustellung ist noch nicht als verfügbar bestätigt. Einzelne Mitteilungen verwenden weiterhin Ihre gespeicherte Themenauswahl.</p>{/if}{/if}
    </div><p class="field-help mt">{current?'Für diese Kombination ist eine persönliche Einstellung gespeichert.':'Noch keine eigene Einstellung gespeichert. Voreinstellung: In-App-Mitteilungen an, E-Mail aus.'}</p><button class="btn primary mt" disabled={busy}>{busy?'Wird gespeichert …':'Meine Auswahl speichern'}<Icon name="check" size={15}/></button>
  </form>
  {#if preferences.length}<details class="panel-body" style="padding-top:0"><summary class="text-link" style="cursor:pointer">Gespeicherte persönliche Einstellungen ansehen</summary><div class="preference-list mt">{#each preferences as row}<div><p><strong>{categories[row.category]||'Themenbereich'}</strong><span>{row.channel==='email'?'E-Mail':'In der Suite'} · {row.enabled?'Aktiviert':'Ausgeschaltet'}{row.quiet_start&&row.quiet_end?' · Ruhezeit '+row.quiet_start.slice(0,5)+'–'+row.quiet_end.slice(0,5):''}</span></p><button type="button" class="btn small" disabled={busy} onclick={()=>edit(row)}>Bearbeiten</button></div>{/each}</div></details>{/if}
</section>
{/if}
<style>.preference-list>div{display:flex;gap:20px;align-items:center;justify-content:space-between;padding:18px 0;border-top:1px solid var(--line)}.preference-list p{display:grid;gap:6px}.preference-list strong{font-weight:550;font-size:13px}.preference-list span{font-size:12px;color:var(--muted)}@media(max-width:760px){.preference-list>div{align-items:flex-start;flex-direction:column;gap:13px}.preference-list strong{font-size:14px}.preference-list span{font-size:13px}}</style>
